package com.bank.ipam;

import java.util.logging.Logger;

// A subnet with a finite number of usable IPs. Real VPC IPs, not overlay.
public class VpcSubnet {
    private static final Logger log = Logger.getLogger(VpcSubnet.class.getName());
    private final String cidr; private final int totalUsable; private int allocated;

    public VpcSubnet(String cidr, int totalUsable) { this.cidr = cidr; this.totalUsable = totalUsable; }

    public boolean allocate(int count) {
        if (allocated + count > totalUsable) {
            log.severe(() -> "subnet " + cidr + " EXHAUSTED: need " + count
                    + " but only " + (totalUsable - allocated) + " free");
            return false;
        }
        allocated += count;
        return true;
    }
    public int free() { return totalUsable - allocated; }
    public int total() { return totalUsable; }
    public int used() { return allocated; }
    public String cidr() { return cidr; }
}
