package com.bank.ipam;

import java.util.logging.Logger;

// Assigns real VPC IPs to Pods; keeps a warm pool; supports prefix delegation.
public class VpcCni {
    private static final Logger log = Logger.getLogger(VpcCni.class.getName());
    private final VpcSubnet subnet;
    private int warmIpsPerNode;        // pre-allocated spares per node
    private boolean prefixDelegation;  // /28 prefix = 16 IPs per ENI slot

    public VpcCni(VpcSubnet subnet, int warmIpsPerNode) { this.subnet = subnet; this.warmIpsPerNode = warmIpsPerNode; }

    public void setWarmIpsPerNode(int n) { this.warmIpsPerNode = n; }
    public void enablePrefixDelegation() { this.prefixDelegation = true; log.info("prefix delegation ON: /28 prefixes (16 IPs each)"); }

    // Starting a node reserves (podsOnNode + warm) IPs; prefix delegation packs more efficiently.
    public boolean startNode(int podsOnNode) {
        int reserve = podsOnNode + warmIpsPerNode;
        if (prefixDelegation) reserve = (int) Math.ceil(reserve / 16.0) * 16; // allocate whole /28 blocks
        boolean ok = subnet.allocate(reserve);
        log.info(() -> "node start: pods=" + podsOnNode + " warm=" + warmIpsPerNode
                + " reserved=" + (podsOnNode + warmIpsPerNode) + (prefixDelegation ? " (prefix /28)" : "")
                + " -> " + (ok ? "OK" : "FAILED (IP exhaustion)"));
        return ok;
    }
}
