package com.bank.ipam;

import java.util.logging.Logger;

// Reports utilization and alerts BEFORE exhaustion (proactive, not reactive).
public class IpCapacityPlanner {
    private static final Logger log = Logger.getLogger(IpCapacityPlanner.class.getName());
    private final double alertThreshold; // e.g. 0.80

    public IpCapacityPlanner(double alertThreshold) { this.alertThreshold = alertThreshold; }

    public void report(VpcSubnet s) {
        double util = (double) s.used() / s.total();
        log.info(() -> String.format("subnet %s utilization=%.0f%% (used %d / %d, free %d)",
                s.cidr(), util * 100, s.used(), s.total(), s.free()));
        if (util >= alertThreshold) {
            log.warning(() -> String.format("ALERT: IP utilization %.0f%% >= %.0f%% — add CIDR / prefix delegation NOW",
                    util * 100, alertThreshold * 100));
        }
    }
}
