package com.bank.ipam;

import java.math.BigDecimal;
import java.util.logging.*;

public class IpamDemo {
    private static final Logger log = Logger.getLogger(IpamDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // Small pilot subnet /27 = 27 usable, warm pool 14 per node -> exhausts fast
        VpcSubnet pilot = new VpcSubnet("10.0.1.0/27", 27);
        VpcCni cni = new VpcCni(pilot, 14);
        IpCapacityPlanner planner = new IpCapacityPlanner(0.80);

        cni.startNode(10); planner.report(pilot);     // reserves 24
        boolean second = cni.startNode(10);            // needs 24 more -> EXHAUSTED
        planner.report(pilot);
        log.info("second node scheduled=" + second + " (Pods stuck ContainerCreating)");

        // FIX: secondary CIDR (bigger pool) + prefix delegation + smaller warm pool
        VpcSubnet secondary = new VpcSubnet("100.64.0.0/22", 1019);
        VpcCni cni2 = new VpcCni(secondary, 2);
        cni2.enablePrefixDelegation();
        cni2.startNode(30); cni2.startNode(30); cni2.startNode(30);
        planner.report(secondary);

        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS — Pods have IPs after CIDR+prefix fix");
    }
}
